settings.custom_liquid:
{% if product.metafields.custom.form_visibility.value == true %}
{% assign booking_date = product.metafields.custom.event_date_and_time %}

{% if booking_date != blank %}
  {% assign now_timestamp = 'now' | date: '%s' | plus: 0 %}
  {% assign booking_timestamp = booking_date | date: '%s' | plus: 0 %}
  {% assign diff_seconds = booking_timestamp | minus: now_timestamp %}
{% endif %}

<div class="color-{{ blocks.settings.custom_liquid_color_scheme }} gradient">
  <div class="booking-wrapper">


    {% if diff_seconds > 0 %}
      <!-- Phone Number -->
      <div class="form-group" id="phone_number">
        <label>Phone Number</label>
        <input
          type="tel"
          name="properties[Phone Number]"
          form="{{ 'product-form-' | append: section.id }}"
          required
        >
      </div>

      <!-- Email ID -->
      <div class="form-group" id="email_id">
        <label>Email ID</label>
        <input
          type="email"
          name="properties[Email ID]"
          form="{{ 'product-form-' | append: section.id }}"
          required
        >
      </div>

      <!-- Rasi -->
      <div class="form-group" id="rasi">
        <label>Rasi</label>
        <select
          name="properties[Rasi]"
          form="{{ 'product-form-' | append: section.id }}"
          required
        >
          <option value="" hidden selected>Select Rasi</option>
          <option>Aries</option>
          <option>Taurus</option>
          <option>Gemini</option>
          <option>Cancer</option>
          <option>Leo</option>
          <option>Virgo</option>
          <option>Libra</option>
          <option>Scorpio</option>
          <option>Sagittarius</option>
          <option>Capricorn</option>
          <option>Aquarius</option>
          <option>Pisces</option>
        </select>
      </div>

      <!-- Nakshatra -->
      <div class="form-group" id="nakshatra">
        <label>Nakshatra</label>
        <select
          name="properties[Nakshatra]"
          form="{{ 'product-form-' | append: section.id }}"
          required
        >
          <option value="" hidden selected>Select Nakshatra</option>
          <option>Ashwini</option>
          <option>Bharani</option>
          <option>Karthigai</option>
          <option>Rohini</option>
          <option>Mrigashirsha</option>
          <option>Arudra</option>
          <option>Punarvasu</option>
          <option>Pushya</option>
          <option>Ashlesha</option>
          <option>Magha</option>
          <option>Purva Phalguni</option>
          <option>Uttara Phalguni</option>
          <option>Hasta</option>
          <option>Chitra</option>
          <option>Swati</option>
          <option>Vishakha</option>
          <option>Anuradha</option>
          <option>Jyeshta</option>
          <option>Moola</option>
          <option>Purva Ashadha</option>
          <option>Uttara Ashadha</option>
          <option>Shravana</option>
          <option>Dhanishta</option>
          <option>Shatabhisha</option>
          <option>Purva Bhadrapada</option>
          <option>Uttara Bhadrapada</option>
          <option>Revati</option>
        </select>
      </div>

      <!-- DOB : 4 Dropdowns -->
      <div class="form-group dob-section" id="date_of_birth">
        <label class="dob-label">Date & Time of Birth :</label>
        <div class="dob-input-wrapper">
          <input
            type="datetime-local"
            name="properties[Date and Time of Birth]"
            form="{{ 'product-form-' | append: section.id }}"
            required
          >
        </div>
      </div>

      <!-- Place of Birth -->
      <div class="form-group" id="place_of_birth">
        <label>Place of Birth :</label>
        <input
          type="text"
          name="properties[Place of Birth]"
          form="{{ 'product-form-' | append: section.id }}"
          required
        >
      </div>

      <!-- Courier -->
      <div class="form-group courier-group" id="prasad_courier">
        <label>Send Prasad by courier? :</label>
        <div class="checkbox-wrapper">
          <input
            type="checkbox"
            name="properties[Prasadham Courier]"
            value="Yes"
            id="PrasadCourier"
            form="{{ 'product-form-' | append: section.id }}"
          >
          <label for="PrasadCourier" style="margin: 0; font-weight: 400;">Yes</label>
        </div>
      </div>



      <!-- Comments -->
      <div class="form-group full-width" id="comments">
        <label>Comments</label>
        <textarea
          rows="4"
          name="properties[Comments]"
          form="{{ 'product-form-' | append: section.id }}"
        ></textarea>
      </div>

    {% else %}
      <div class="booking-closing">
        <p class="booking-closed">Booking Closed</p>
      </div>
    {% endif %}
  </div>
</div>
{% endif %}

<style>
  .booking-wrapper {
    max-width: 650px;
    margin: 20px auto;
    padding: 28px;
    border-radius: 16px;

    background: rgb(var(--color-background));
    color: rgb(var(--color-foreground));
  }

  .booking-closing {
    margin-bottom: 24px;
    text-align: center;
  }

  .form-countdown-text {
    font-size: 20px;
    font-weight: 700;
    color: rgb(var(--color-button));
    text-transform: uppercase;
    letter-spacing: 1px;
  }

  .booking-closed {
    font-size: 18px;
    color: rgba(var(--color-foreground), 0.6);
    font-style: italic;
  }

  /* FORM GRID */
  .form-group {
    margin-bottom: 18px;
    display: flex;
    flex-direction: column;
  }

  /* 2 COLUMN (desktop & tablet landscape) */
  @media (min-width: 750px) {
    .booking-wrapper {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 16px 24px;
    }

    .booking-closing {
      grid-column: span 2;
    }

    .full-width {
      grid-column: span 2;
    }
  }

  /* MOBILE/TABLET PORTRAIT SPECIFIC (< 750px) */
  @media (max-width: 749px) {
    .booking-wrapper {
      padding: 24px;
      margin: 15px auto;
    }

    .form-group input,
    .form-group select,
    .form-group textarea {
      min-height: 44px;
    }
  }

  /* LABEL */
  .form-group label {
    font-size: 14px;
    font-weight: 600;
    margin-bottom: 8px;
    color: rgb(var(--color-foreground));
  }

  /* INPUTS */
  .form-group input,
  .form-group select,
  .form-group textarea {
    width: 100%;
    box-sizing: border-box;
    padding: 10px 12px;
    border-radius: 8px;
    border: 1px solid rgba(var(--color-foreground), 0.3);
    font-size: 14px;

    background: rgb(var(--color-background));
    color: rgb(var(--color-foreground));
    transition: all 0.25s ease;
  }

  /* DOB SECTION */
  .dob-section {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
  }

  .dob-label {
    margin-bottom: 4px !important;
    white-space: nowrap;
  }

  .dob-input-wrapper {
    width: 100%;
  }

  .dob-input-wrapper input {
    width: 100%;
  }

  @media (max-width: 480px) {
    .dob-grid select {
      flex: 1 1 100%;
    }
  }

  /* COURIER GROUP */
  .courier-group {
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: flex-start;
    gap: 10px;
  }

  .courier-group label {
    margin-bottom: 0 !important;
  }

  .checkbox-wrapper {
    display: flex;
    align-items: center;
    gap: 5px;
  }

  input[type='checkbox'] {
    width: 18px;
    height: 18px;
    margin: 0;
    accent-color: rgb(var(--color-button));
  }

  /* FOCUS EFFECT */
  .form-group input:focus,
  .form-group select:focus,
  .form-group textarea:focus {
    border-color: rgb(var(--color-button));
    box-shadow: 0 0 0 3px rgba(var(--color-button), 0.15);
    outline: none;
  }

  textarea {
    resize: vertical;
    min-height: 80px;
  }

  /* PREVENT ZOOM AND OPTIMIZE TOUCH (< 750px) */
  @media (max-width: 749px) {
    .form-group input,
    .form-group select,
    .form-group textarea {
      font-size: 16px;
      min-height: 44px;
    }

    .booking-wrapper {
      width: 95%;
      padding: 20px;
    }
  }
</style>

{% assign booking_date = product.metafields.custom.event_date_and_time %}

{% if booking_date != blank %}
  {% assign now_timestamp = 'now' | date: '%s' | plus: 0 %}
  {% assign booking_timestamp = booking_date | date: '%s' | plus: 0 %}
  {% assign diff_seconds = booking_timestamp | minus: now_timestamp %}
{% endif %}

<div class="booking-wrapper">

  <!-- ✅ FORM SHOW ONLY IF BOOKING OPEN -->
  {% if diff_seconds > 0 %}

    <!-- Date of Birth -->
    <div class="form-group">
      <label>Date of Birth</label>
      <input type="date"
        name="properties[Date of Birth]"
        form="{{ 'product-form-' | append: section.id }}"
        required>
    </div>

    <!-- Birth Time -->
    <div class="form-group">
      <label>Birth Time</label>
      <input type="time"
        name="properties[Birth Time]"
        form="{{ 'product-form-' | append: section.id }}"
        required>
    </div>

    <!-- Homam Date -->
    {% assign show_homam = product.metafields.custom.homam_date_picker %}
    {% if show_homam == true %}
      <div class="form-group">
        <label>Homam Date</label>
        <input type="date"
          name="properties[Homam Date]"
          form="{{ 'product-form-' | append: section.id }}"
          required>
      </div>
    {% endif %}

    <!-- Rasi -->
    <div class="form-group">
      <label>Rasi</label>
      <select name="properties[Rasi]"
        form="{{ 'product-form-' | append: section.id }}"
        required>
        <option value="" hidden selected>Please select</option>
        <option>Aries</option>
        <option>Taurus</option>
        <option>Gemini</option>
        <option>Cancer</option>
        <option>Leo</option>
        <option>Virgo</option>
        <option>Libra</option>
        <option>Scorpio</option>
        <option>Sagittarius</option>
        <option>Capricorn</option>
        <option>Aquarius</option>
        <option>Pisces</option>
      </select>
    </div>

    <!-- Nakshatra -->
    <div class="form-group">
      <label>Nakshatra</label>
      <select name="properties[Nakshatra]"
        form="{{ 'product-form-' | append: section.id }}"
        required>
        <option value="" hidden selected>Please select</option>
        <option>Ashwini</option>
        <option>Bharani</option>
        <option>Karthigai</option>
        <option>Rohini</option>
        <option>Mrigashirsha</option>
        <option>Arudra</option>
        <option>Punarvasu</option>
        <option>Pushya</option>
        <option>Ashlesha</option>
        <option>Magha</option>
        <option>Purva Phalguni</option>
        <option>Uttara Phalguni</option>
        <option>Hasta</option>
        <option>Chitra</option>
        <option>Swati</option>
        <option>Vishakha</option>
        <option>Anuradha</option>
        <option>Jyeshta</option>
        <option>Moola</option>
        <option>Purva Ashadha</option>
        <option>Uttara Ashadha</option>
        <option>Shravana</option>
        <option>Dhanishta</option>
        <option>Shatabhisha</option>
        <option>Purva Bhadrapada</option>
        <option>Uttara Bhadrapada</option>
        <option>Revati</option>
      </select>
    </div>

    <!-- Place -->
    <div class="form-group">
      <label>Place Of Birth</label>
      <input type="text"
        name="properties[Place Of Birth]"
        form="{{ 'product-form-' | append: section.id }}"
        placeholder="Enter place"
        required>
    </div>

    <!-- Comments -->
    <div class="form-group">
      <label>Comments</label>
      <textarea rows="4"
        name="properties[Comments]"
        form="{{ 'product-form-' | append: section.id }}"
        placeholder="Optional notes"></textarea>
    </div>

  {% endif %}

</div>

<style>

/* Form group */
.form-group {
  margin-bottom: 18px;
  display: flex;
  flex-direction: column;
}

/* Labels */
.form-group label {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 6px;
  color: rgb(var(--color-foreground));
}

/* Inputs */
.form-group input,
.form-group select,
.form-group textarea {
  padding: 12px;
  border-radius: 12px;
  border: 1px solid rgba(var(--color-foreground), 0.2);
  background: rgb(var(--color-background));
  color: rgb(var(--color-foreground));
  font-size: 14px;
  transition: all 0.3s ease;
}

/* Focus */
.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  border-color: rgb(var(--color-button));
  box-shadow: 0 0 0 2px rgba(var(--color-button), 0.15);
  outline: none;
}

/* Placeholder */
.form-group input::placeholder,
.form-group textarea::placeholder {
  color: rgba(var(--color-foreground), 0.5);
}

/* Dropdown */
.form-group select {
  cursor: pointer;
}

/* Textarea */
textarea {
  resize: vertical;
  min-height: 100px;
}

/* Mobile */
@media (max-width: 600px) {
  .booking-wrapper {
    padding: 15px;
  }

  .form-group input,
  .form-group select,
  .form-group textarea {
    font-size: 13px;
    padding: 10px;
  }
}
</style>
